<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Login - Server Control</title>
  <style>
    :root {
      --bg: #ffffff;
      --ink: #111827;
      --muted: #6b7280;
      --line: #e5e7eb;
      --surface: #f9fafb;
      --accent: #000000;
      --accent-hover: #374151;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background: var(--bg);
      color: var(--ink);
    }

    main {
      width: min(380px, calc(100% - 32px));
      padding: 0;
    }

    .eyebrow {
      margin-bottom: 12px;
      color: var(--muted);
      font-size: 13px;
      font-weight: 700;
      letter-spacing: 0.05em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0 0 32px;
      font-size: 40px;
      line-height: 1.1;
      letter-spacing: -0.04em;
      font-weight: 800;
    }

    label {
      display: block;
      margin: 16px 0 8px;
      color: var(--ink);
      font-size: 14px;
      font-weight: 600;
    }

    input {
      width: 100%;
      height: 48px;
      padding: 10px 14px;
      border: 1px solid var(--line);
      border-radius: 8px;
      background: var(--surface);
      color: var(--ink);
      font: inherit;
      transition: border-color 0.2s, background 0.2s;
    }

    input:focus {
      outline: none;
      border-color: var(--accent);
      background: #ffffff;
    }

    button {
      width: 100%;
      height: 48px;
      margin-top: 32px;
      border: 0;
      border-radius: 8px;
      background: var(--accent);
      color: #ffffff;
      font: inherit;
      font-weight: 600;
      cursor: pointer;
      transition: background 0.2s;
    }

    button:hover {
      background: var(--accent-hover);
    }
  </style>
</head>
<body>
  <main>
    <div class="eyebrow">Authentication</div>
    <h1>Sign In</h1>
    <form method="post" action="/login">
      <label for="username">Username</label>
      <input id="username" name="username" autocomplete="username" required>

      <label for="password">Password</label>
      <input id="password" name="password" type="password" autocomplete="current-password" required>

      <button type="submit">Continue to Server</button>
    </form>
  </main>
</body>
</html>

